import itertools

def check_beats(die1, die2):
    count = 0
    for a in die1:
        for b in die2:
            if a > b:
                count += 1
    return count > 18

def solve():
    # Values are in {0, ..., 11}
    # Each die has 6 faces, sorted
    # 5 dice

    # Let's try a search. Since the search space is large, maybe we can use some heuristics.
    # Or just use a simple backtracking search.

    import random

    # Try random search first
    for _ in range(100000):
        dice = []
        for _ in range(5):
            die = sorted([random.randint(0, 11) for _ in range(6)])
            dice.append(die)

        valid = True
        for i in range(5):
            if not check_beats(dice[i], dice[(i+1)%5]):
                valid = False
                break
        if valid:
            return dice
    return None

result = solve()
print(result)
